<?php
declare(strict_types=1);
function franchise_rows(string $sql,array $p=[]): array {try{$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll();}catch(Throwable $e){return [];}}
function franchise_row(string $sql,array $p=[]): ?array {$r=franchise_rows($sql,$p);return $r?$r[0]:null;}
function franchise_list(): array {return franchise_rows("SELECT f.*,c.name city_name,c.slug city_slug,u.name manager_name,u.email manager_email FROM city_franchises f JOIN cities c ON c.id=f.city_id LEFT JOIN users u ON u.id=f.manager_user_id ORDER BY FIELD(f.status,'active','draft','suspended'),c.name");}
function franchise_metrics(int $cityId): array {$m=['businesses'=>0,'products'=>0,'orders'=>0,'marketplace_gmv'=>0,'city_content'=>0,'news'=>0];try{$q=db()->prepare('SELECT COUNT(*) FROM businesses WHERE city_id=? AND status=1');$q->execute([$cityId]);$m['businesses']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM store_products WHERE city_id=? AND status='published'");$q->execute([$cityId]);$m['products']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(DISTINCT o.id),COALESCE(SUM(o.grand_total),0) FROM store_orders o JOIN store_order_items oi ON oi.order_id=o.id JOIN store_products p ON p.id=oi.product_id WHERE p.city_id=? AND o.status NOT IN ('cancelled')");$q->execute([$cityId]);$r=$q->fetch();$m['orders']=(int)($r[0]??0);$m['marketplace_gmv']=(float)($r[1]??0);$q=db()->prepare("SELECT COUNT(*) FROM city_portal_items WHERE city_id=? AND status='published'");$q->execute([$cityId]);$m['city_content']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM news_posts WHERE city_id=? AND status='published'");$q->execute([$cityId]);$m['news']=(int)$q->fetchColumn();}catch(Throwable $e){}return $m;}
function franchise_save(array $d,int $by): int {$city=(int)($d['city_id']??0);if($city<1)throw new RuntimeException('Choose a city.');$manager=(int)($d['manager_user_id']??0)?:null;$status=in_array((string)($d['status']??'draft'),['draft','active','suspended'],true)?$d['status']:'draft';$shares=[];foreach(['revenue_share_percent','marketplace_share_percent','ad_share_percent','subscription_share_percent'] as $k)$shares[$k]=max(0,min(100,(float)($d[$k]??20)));$existing=franchise_row('SELECT id FROM city_franchises WHERE city_id=?',[$city]);if($existing){db()->prepare('UPDATE city_franchises SET manager_user_id=?,franchise_name=?,public_slug=?,custom_domain=?,revenue_share_percent=?,marketplace_share_percent=?,ad_share_percent=?,subscription_share_percent=?,support_email=?,support_phone=?,status=? WHERE id=?')->execute([$manager,trim((string)($d['franchise_name']??''))?:null,trim((string)($d['public_slug']??''))?:null,trim((string)($d['custom_domain']??''))?:null,$shares['revenue_share_percent'],$shares['marketplace_share_percent'],$shares['ad_share_percent'],$shares['subscription_share_percent'],trim((string)($d['support_email']??''))?:null,trim((string)($d['support_phone']??''))?:null,$status,$existing['id']]);return (int)$existing['id'];}db()->prepare('INSERT INTO city_franchises(city_id,manager_user_id,franchise_name,public_slug,custom_domain,revenue_share_percent,marketplace_share_percent,ad_share_percent,subscription_share_percent,support_email,support_phone,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$city,$manager,trim((string)($d['franchise_name']??''))?:null,trim((string)($d['public_slug']??''))?:null,trim((string)($d['custom_domain']??''))?:null,$shares['revenue_share_percent'],$shares['marketplace_share_percent'],$shares['ad_share_percent'],$shares['subscription_share_percent'],trim((string)($d['support_email']??''))?:null,trim((string)($d['support_phone']??''))?:null,$status]);return (int)db()->lastInsertId();}
function franchise_for_manager(int $uid): array {return franchise_rows("SELECT f.*,c.name city_name FROM city_franchises f JOIN cities c ON c.id=f.city_id WHERE f.manager_user_id=? AND f.status='active' ORDER BY c.name",[$uid]);}
